      "2dbcecd9": "የአሽከርካሪ መቀመጫ ማስተካከያ：ወደፊት-ወደኋላ ማስተካከያ፤ የጀርባ መደገፊያ ማስተካከያ፤ ከፍታ ማስተካከያ(2-way) -> ወደፊት-ወደኋላ ማስተካከያ; የጀርባ መደገፊያ ማስተካከያ; ከፍታ ማስተካከያ(2-way); የእግር ማሳረፊያ ማስተካከያ：አማራጭ፤ የወገብ ድጋፍ(4-way)",
      "81edd9ec": "የፊት መቀመጫ ተግባራት：ማሞቂያ፤ አየር ማስገቢያ -> ማሞቂያ; አየር ማስገቢያ; ማሳጅ：አማራጭ፤ ማሳጅ(የተሳፋሪ ጎን ብቻ)፤ የራስ መደገፊያ ድምፅ ማጉያ(የአሽከርካሪ ጎን ብቻ)",
      efb80ac6: "የድምፅ ማጉያ ብዛት：8ድምፅ ማጉያዎች -> 20ድምፅ ማጉያዎች",
