      "5f98d1a6": "የተሳፋሪ መቀመጫ ማስተካከያ：ወደፊት-ወደኋላ ማስተካከያ; የጀርባ መደገፊያ ማስተካከያ; የእግር ማሳረፊያ ማስተካከያ：አማራጭ",
