      "96de233c": "ከዚህ ትሪም የተወረሰ 520 MaxBEV ትሪም：ኤሌክትሪክ የኋላ በር：መደበኛ",
      be6e0059: "ከዚህ ትሪም የተወረሰ 520 MaxBEV ትሪም：የኋላ በር ቦታ ማስታወሻ：መደበኛ",
      b3f621ec: "ከዚህ ትሪም የተወረሰ 520 MaxBEV ትሪም：የአሽከርካሪ መቀመጫ ማስተካከያ：ወደፊት-ወደኋላ ማስተካከያ; የጀርባ መደገፊያ ማስተካከያ; ከፍታ ማስተካከያ(2-way); የወገብ ድጋፍ(2-way)：አማራጭ -> ወደፊት-ወደኋላ ማስተካከያ፤ የጀርባ መደገፊያ ማስተካከያ፤ ከፍታ ማስተካከያ(2-way)፤ የወገብ ድጋፍ(2-way)",
      "730fd18a": "ከዚህ ትሪም የተወረሰ 520 MaxBEV ትሪም：የተሳፋሪ መቀመጫ ማስተካከያ：ወደፊት-ወደኋላ ማስተካከያ; የጀርባ መደገፊያ ማስተካከያ; የእግር ማሳረፊያ ማስተካከያ：አማራጭ -> ወደፊት-ወደኋላ ማስተካከያ፤ የጀርባ መደገፊያ ማስተካከያ፤ የእግር ማሳረፊያ ማስተካከያ",
      "1b54aeab": "ከዚህ ትሪም የተወረሰ 520 MaxBEV ትሪም：የፊት መቀመጫ ተግባራት：ማሞቂያ：አማራጭ; አየር ማስገቢያ：አማራጭ -> ማሞቂያ፤ አየር ማስገቢያ",
      "9aff5e61": "ከዚህ ትሪም የተወረሰ 520 UltraBEV ትሪም：የካቢን አየር ማጣሪያ：መደበኛ",
      b98a1bd4: "ከዚህ ትሪም የተወረሰ 520 UltraBEV ትሪም：የአሽከርካሪ መቀመጫ ማስተካከያ：ወደፊት-ወደኋላ ማስተካከያ፤ የጀርባ መደገፊያ ማስተካከያ፤ ከፍታ ማስተካከያ(2-way)፤ የወገብ ድጋፍ(2-way) -> ወደፊት-ወደኋላ ማስተካከያ፤ የጀርባ መደገፊያ ማስተካከያ፤ ከፍታ ማስተካከያ(2-way)፤ የወገብ ድጋፍ(4-way)",
      d11293dc: "ከዚህ ትሪም የተወረሰ 520 UltraBEV ትሪም：የተሳፋሪ መቀመጫ ማስተካከያ：ወደፊት-ወደኋላ ማስተካከያ፤ የጀርባ መደገፊያ ማስተካከያ፤ የእግር ማሳረፊያ ማስተካከያ -> ወደፊት-ወደኋላ ማስተካከያ፤ የጀርባ መደገፊያ ማስተካከያ፤ ከፍታ ማስተካከያ(4-way)፤ የእግር ማሳረፊያ ማስተካከያ፤ የወገብ ድጋፍ(4-way)",
      d69573af: "ከዚህ ትሪም የተወረሰ 520 UltraBEV ትሪም：የፊት መቀመጫ ተግባራት：ማሞቂያ፤ አየር ማስገቢያ -> ማሞቂያ፤ አየር ማስገቢያ፤ ማሳጅ",
      "8677b4ed": "ከዚህ ትሪም የተወረሰ 520 UltraBEV ትሪም：የድምፅ ማጉያ ብዛት：8ድምፅ ማጉያዎች -> 14ድምፅ ማጉያዎች",
      b898b754: "የአሽከርካሪ መቀመጫ ማስተካከያ：ወደፊት-ወደኋላ ማስተካከያ፤ የጀርባ መደገፊያ ማስተካከያ፤ ከፍታ ማስተካከያ(2-way)፤ የወገብ ድጋፍ(4-way) -> ወደፊት-ወደኋላ ማስተካከያ፤ የጀርባ መደገፊያ ማስተካከያ፤ ከፍታ ማስተካከያ(2-way)፤ የወገብ ድጋፍ(2-way)",
      "454c5f24": "የተሳፋሪ መቀመጫ ማስተካከያ：ወደፊት-ወደኋላ ማስተካከያ፤ የጀርባ መደገፊያ ማስተካከያ፤ ከፍታ ማስተካከያ(4-way)፤ የእግር ማሳረፊያ ማስተካከያ፤ የወገብ ድጋፍ(4-way) -> ወደፊት-ወደኋላ ማስተካከያ፤ የጀርባ መደገፊያ ማስተካከያ፤ የእግር ማሳረፊያ ማስተካከያ",
      "8fa4b15c": "የአሽከርካሪ መቀመጫ ማስተካከያ：ወደፊት-ወደኋላ ማስተካከያ፤ የጀርባ መደገፊያ ማስተካከያ፤ ከፍታ ማስተካከያ(2-way)፤ የወገብ ድጋፍ(2-way) -> ወደፊት-ወደኋላ ማስተካከያ፤ የጀርባ መደገፊያ ማስተካከያ፤ ከፍታ ማስተካከያ(2-way)፤ የወገብ ድጋፍ(4-way)",
      caad28b4: "የተሳፋሪ መቀመጫ ማስተካከያ：ወደፊት-ወደኋላ ማስተካከያ፤ የጀርባ መደገፊያ ማስተካከያ፤ የእግር ማሳረፊያ ማስተካከያ -> ወደፊት-ወደኋላ ማስተካከያ፤ የጀርባ መደገፊያ ማስተካከያ፤ ከፍታ ማስተካከያ(4-way)፤ የእግር ማሳረፊያ ማስተካከያ፤ የወገብ ድጋፍ(4-way)",
