      "365d74fd": "የሁለተኛ ረድፍ መቀመጫ ማስተካከያ：ወደፊት-ወደኋላ ማስተካከያ; የጀርባ መደገፊያ ማስተካከያ; ከፍታ ማስተካከያ; ወገብ ማስተካከያ; የእግር ማሳረፊያ ማስተካከያ; መዞር ማስተካከያ：አማራጭ -> ወደፊት-ወደኋላ ማስተካከያ; የጀርባ መደገፊያ ማስተካከያ; ከፍታ ማስተካከያ; ወገብ ማስተካከያ; የእግር ማሳረፊያ ማስተካከያ; መዞር ማስተካከያ：አማራጭ፤ የእግር መደገፊያ ማስተካከያ",
      "3aec0f14": "የአሽከርካሪ እገዛ ቺፕ：NVIDIA Drive Thor-U -> 2 pcs NVIDIA Drive Thor-U",
      "5ffd5b6a": "የአሽከርካሪ እገዛ ስርዓት：Qianli Haohan H7; Qianli Haohan H9：አማራጭ -> Qianli Haohan H9",
      a4dcb573: "የአሽከርካሪ መቀመጫ ማስተካከያ：ወደፊት-ወደኋላ ማስተካከያ፤ የጀርባ መደገፊያ ማስተካከያ፤ ከፍታ ማስተካከያ(4-way)፤ የእግር ማሳረፊያ ማስተካከያ፤ የወገብ ድጋፍ(4-way) -> ወደፊት-ወደኋላ ማስተካከያ፤ የጀርባ መደገፊያ ማስተካከያ፤ ከፍታ ማስተካከያ(4-way)፤ የእግር ማሳረፊያ ማስተካከያ፤ የወገብ ድጋፍ(4-way)፤ የጎን ድጋፍ(ንቁ)",
      "199e268d": "የሁለተኛ ረድፍ መቀመጫ ማስተካከያ：ወደፊት-ወደኋላ ማስተካከያ; የጀርባ መደገፊያ ማስተካከያ; ከፍታ ማስተካከያ; ወገብ ማስተካከያ; የእግር ማሳረፊያ ማስተካከያ; መዞር ማስተካከያ：አማራጭ፤ የእግር መደገፊያ ማስተካከያ -> ወደፊት-ወደኋላ ማስተካከያ፤ የጀርባ መደገፊያ ማስተካከያ፤ ከፍታ ማስተካከያ፤ ወገብ ማስተካከያ፤ የእግር ማሳረፊያ ማስተካከያ፤ መዞር ማስተካከያ፤ የእግር መደገፊያ ማስተካከያ",
