      "9ce10e34": "ከዚህ ትሪም የተወረሰ DM-i Smart Driving ትሪም 125KMPilot ትሪም：የአሽከርካሪ እገዛ ስርዓት：DiPilot 300 -> DiPilot 100",
      "41e6151f": "ከዚህ ትሪም የተወረሰ DM-i Smart Driving ትሪም 125KMPilot ትሪም：የአሽከርካሪ መቀመጫ ማስተካከያ：ወደፊት-ወደኋላ ማስተካከያ፤ የጀርባ መደገፊያ ማስተካከያ፤ ከፍታ ማስተካከያ(4-way)፤ የወገብ ድጋፍ(4-way) -> ወደፊት-ወደኋላ ማስተካከያ፤ የጀርባ መደገፊያ ማስተካከያ፤ ከፍታ ማስተካከያ(2-way)",
