      ab79a327: "ከዚህ ትሪም የተወረሰ EV Smart Driving ትሪም 605KMPilot ትሪም：የመቀመጫ ቁሳቁስ：ቆዳ -> ሰው ሠራሽ ቆዳ",
      "87dd66ab": "ከዚህ ትሪም የተወረሰ EV Smart Driving ትሪም 605KMPilot ትሪም：የፊት መቀመጫ ተግባራት：ማሞቂያ፤ አየር ማስገቢያ፤ ማሳጅ -> ማሞቂያ፤ አየር ማስገቢያ",
