      "629c42e2": "የድምፅ ማጉያ ብዛት：14ድምፅ ማጉያዎች; 25ድምፅ ማጉያዎች：አማራጭ",
      dde62bbc: "96.3 kWh LFP ባትሪ",
      c04ff5ef: "የአሽከርካሪ መቀመጫ ማስተካከያ：ወደፊት-ወደኋላ ማስተካከያ፤ የጀርባ መደገፊያ ማስተካከያ፤ ከፍታ ማስተካከያ(4-way)፤ የወገብ ድጋፍ(4-way) -> ወደፊት-ወደኋላ ማስተካከያ; የጀርባ መደገፊያ ማስተካከያ; ከፍታ ማስተካከያ(4-way); የእግር ማሳረፊያ ማስተካከያ：አማራጭ፤ የወገብ ድጋፍ(4-way)",
      cdb874bd: "የተሳፋሪ መቀመጫ ማስተካከያ：ወደፊት-ወደኋላ ማስተካከያ፤ የጀርባ መደገፊያ ማስተካከያ፤ ከፍታ ማስተካከያ(2-way) -> ወደፊት-ወደኋላ ማስተካከያ; የጀርባ መደገፊያ ማስተካከያ; ከፍታ ማስተካከያ(2-way); ከፍታ ማስተካከያ(4-way)：አማራጭ; የእግር ማሳረፊያ ማስተካከያ：አማራጭ",
      "17cb80cb": "የፊት መቀመጫ ተግባራት：ማሞቂያ፤ አየር ማስገቢያ፤ የራስ መደገፊያ ድምፅ ማጉያ(የአሽከርካሪ ጎን ብቻ) -> ማሞቂያ; አየር ማስገቢያ; ማሳጅ：አማራጭ፤ የራስ መደገፊያ ድምፅ ማጉያ(የአሽከርካሪ ጎን ብቻ)",
      "5d29f889": "101.7 kWh NCM ባትሪ",
      "04141ad4": "የድምፅ ማጉያ ብዛት：14ድምፅ ማጉያዎች; 25ድምፅ ማጉያዎች：አማራጭ -> 25ድምፅ ማጉያዎች",
      "544f6b52": "የመቀመጫ ቁሳቁስ：ቆዳ：አማራጭ፤ ሰው ሠራሽ ቆዳ -> ቆዳ：አማራጭ; ሰው ሠራሽ ቆዳ; ቆዳ/Alcantara ድብልቅ：አማራጭ",
      "5bbc1a1d": "የአሽከርካሪ መቀመጫ ማስተካከያ：ወደፊት-ወደኋላ ማስተካከያ; የጀርባ መደገፊያ ማስተካከያ; ከፍታ ማስተካከያ(4-way); የእግር ማሳረፊያ ማስተካከያ：አማራጭ፤ የወገብ ድጋፍ(4-way) -> ወደፊት-ወደኋላ ማስተካከያ; የጀርባ መደገፊያ ማስተካከያ; ከፍታ ማስተካከያ(4-way); የእግር ማሳረፊያ ማስተካከያ：አማራጭ; የወገብ ድጋፍ(4-way); የጎን ድጋፍ(ንቁ)：አማራጭ",
      "485f6b5a": "የተሳፋሪ መቀመጫ ማስተካከያ：ወደፊት-ወደኋላ ማስተካከያ; የጀርባ መደገፊያ ማስተካከያ; ከፍታ ማስተካከያ(2-way); ከፍታ ማስተካከያ(4-way)：አማራጭ; የእግር ማሳረፊያ ማስተካከያ：አማራጭ -> ወደፊት-ወደኋላ ማስተካከያ; የጀርባ መደገፊያ ማስተካከያ; ከፍታ ማስተካከያ(2-way); ከፍታ ማስተካከያ(4-way)：አማራጭ; የእግር ማሳረፊያ ማስተካከያ：አማራጭ; የወገብ ድጋፍ(4-way)：አማራጭ",
